const initializeWamEnv=apiVersion=>{const audioWorkletGlobalScope=globalThis;if(audioWorkletGlobalScope.AudioWorkletProcessor&&audioWorkletGlobalScope.webAudioModules)return;const moduleScopes=new Map;const groups=new Map;class WamEnv{constructor(){}get apiVersion(){return apiVersion}getModuleScope(moduleId){if(!moduleScopes.has(moduleId))moduleScopes.set(moduleId,{});return moduleScopes.get(moduleId)}getGroup(groupId,groupKey){const group=groups.get(groupId);if(group.validate(groupKey))return group;else throw"Invalid key"}addGroup(group){if(!groups.has(group.groupId))groups.set(group.groupId,group)}removeGroup(group){groups.delete(group.groupId)}addWam(wam){const group=groups.get(wam.groupId);group.addWam(wam)}removeWam(wam){const group=groups.get(wam.groupId);group.removeWam(wam)}connectEvents(groupId,fromId,toId,output=0){const group=groups.get(groupId);group.connectEvents(fromId,toId,output)}disconnectEvents(groupId,fromId,toId,output){const group=groups.get(groupId);group.disconnectEvents(fromId,toId,output)}emitEvents(from,...events){const group=groups.get(from.groupId);group.emitEvents(from,...events)}}if(audioWorkletGlobalScope.AudioWorkletProcessor){if(!audioWorkletGlobalScope.webAudioModules)audioWorkletGlobalScope.webAudioModules=new WamEnv}};export default initializeWamEnv;